from collections import Counter

def solve(grid):
    m = len(grid)
    n = len(grid[0]) if m else 0

    # count each value in the whole grid
    cnt = Counter()
    for row in grid:
        cnt.update(row)

    # the value that fills one entire row and one entire column appears (m+n-1) times
    target = m + n - 1
    cross_val = None
    for v, c in cnt.items():
        if c == target:
            cross_val = v
            break

    # locate the completely uniform row and column (the cross)
    cross_row = -1
    for i in range(m):
        if all(grid[i][j] == cross_val for j in range(n)):
            cross_row = i
            break

    cross_col = -1
    for j in range(n):
        if all(grid[i][j] == cross_val for i in range(m)):
            cross_col = j
            break

    # background: most common value outside the cross
    bg_cnt = Counter()
    for i in range(m):
        for j in range(n):
            if i == cross_row or j == cross_col:
                continue
            bg_cnt[grid[i][j]] += 1

    background = bg_cnt.most_common(1)[0][0] if bg_cnt else None

    # find the odd cell (different from both cross value and background)
    odd = None
    for i in range(m):
        for j in range(n):
            if i == cross_row or j == cross_col:
                continue
            val = grid[i][j]
            if val != cross_val and val != background:
                odd = (i, j)
                break
        if odd:
            break

    # determine which quadrant contains the odd cell
    r, c = odd
    if r < cross_row and c < cross_col:
        top, bottom, left, right = 0, cross_row - 1, 0, cross_col - 1
    elif r < cross_row and c > cross_col:
        top, bottom, left, right = 0, cross_row - 1, cross_col + 1, n - 1
    elif r > cross_row and c < cross_col:
        top, bottom, left, right = cross_row + 1, m - 1, 0, cross_col - 1
    else:  # r > cross_row and c > cross_col
        top, bottom, left, right = cross_row + 1, m - 1, cross_col + 1, n - 1

    # extract the selected quadrant
    result = [grid[i][left:right + 1] for i in range(top, bottom + 1)]
    return result

